// REPORT-DATEN AUFBEREITEN v9 – safeAll(), robuste Diagnose
// Modus: runOnceForAllItems
// Input: alle Items der 4 DB-Lade-Nodes via append-Merge-Kette
// safeAll() liest $() mit Fallback auf leere Liste

const sd    = $getWorkflowStaticData('global');
const heute = new Date().toISOString().substring(0, 10);

// safeAll: versucht $() zu lesen, gibt [] zurück bei Fehler
function safeAll(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!items || items.length === 0) return [];
    return items.map(i => i.json);
  } catch(e) {
    return [];
  }
}

// Quellen direkt laden
const fundamentaldaten = safeAll('DB: Fundamentaldaten laden');
const alleNews         = safeAll('DB: Heutige News laden');
const techAusDB        = safeAll('DB: Technische Signale laden');
const marktKontext     = safeAll('DB: Marktumfeld laden');
const empfehlungenRows = safeAll('DB: Empfehlungen laden');

// ─── Diagnose ────────────────────────────────────────────────────────────────
const diagnose = {
  fundamental_count:   fundamentaldaten.length,
  fundamental_ok:      fundamentaldaten.filter(i => i.status === 'ok').length,
  fundamental_fehler:  fundamentaldaten.filter(i => i.status === 'fehler').length,
  tech_signale_count:  techAusDB.length,
  tech_signale_heute:  techAusDB.filter(s => String(s.datum || '').startsWith(heute)).length,
  markt_kontext_count: marktKontext.length,
  news_total:          alleNews.length,
  quellen_leer:        []
};
if (fundamentaldaten.length === 0) diagnose.quellen_leer.push('DB: Fundamentaldaten laden');
if (techAusDB.length === 0)        diagnose.quellen_leer.push('DB: Technische Signale laden');
if (marktKontext.length === 0)     diagnose.quellen_leer.push('DB: Marktumfeld laden');
if (alleNews.length === 0)         diagnose.quellen_leer.push('DB: Heutige News laden');

// ─── Ticker→Sektor-Zuordnung aus den technischen Signalen (Watchlist-Quelle) ──
const tickerSektorMap = {};
for (const s of techAusDB) {
  if (s.ticker && s.sektor) tickerSektorMap[String(s.ticker).trim()] = String(s.sektor).trim();
}

// ─── Sektor-Schlüsselwörter für sektor-weite News (wirkungsebene = 'sektor') ──
const SEKTOR_KEYWORDS = {
  'Auto':         ['auto', 'automobil', 'fahrzeug', 'e-auto', 'elektroauto', 'zulieferer', 'pkw'],
  'Energie':      ['energie', 'strom', 'gas', 'öl', 'ölpreis', 'kraftwerk', 'erneuerbare'],
  'Chemie':       ['chemie', 'chemiekonzern', 'chemieindustrie'],
  'Banken':       ['bank', 'banken', 'zins', 'zinsen', 'ezb', 'kredit', 'finanzsektor'],
  'Pharma':       ['pharma', 'medikament', 'arznei', 'biotech', 'arzneimittel'],
  'Telekom':      ['telekom', 'mobilfunk', '5g', 'netzausbau', 'glasfaser'],
  'Versicherung': ['versicherung', 'versicherer'],
  'Technologie':  ['software', 'chip', 'halbleiter', ' ki ', 'cloud', 'tech-branche'],
  'Industrie':    ['industrie', 'maschinenbau', 'anlagenbau', 'industriekonzern'],
  'Sport':        ['sportartikel', 'sportbekleidung'],
  'Konsumgüter':  ['konsumgüter', 'konsumgüterkonzern'],
  'Gesundheit':   ['gesundheitswesen', 'klinik', 'medizintechnik']
};

function ermittleSektorenAusText(text) {
  const t = String(text || '').toLowerCase();
  const treffer = [];
  for (const [sektor, keywords] of Object.entries(SEKTOR_KEYWORDS)) {
    if (keywords.some(k => t.includes(k))) treffer.push(sektor);
  }
  return treffer;
}

function erweitereTickerFuerSektorNews(n) {
  const bereitsGenannt = Array.isArray(n.betroffene_ticker)
    ? n.betroffene_ticker
    : String(n.betroffene_ticker || '').split(',').map(t => t.trim()).filter(Boolean);

  if (n.wirkungsebene !== 'sektor') {
    return { ...n, betroffene_ticker_erweitert: bereitsGenannt, sektor_treffer: [] };
  }

  const matchText = [n.titel, n.begruendung, n.begruendung_tickerbezug].filter(Boolean).join(' ');
  const sektorTreffer = ermittleSektorenAusText(matchText);

  const zusaetzlicheTicker = Object.entries(tickerSektorMap)
    .filter(([, sektor]) => sektorTreffer.includes(sektor))
    .map(([ticker]) => ticker);

  const erweitert = Array.from(new Set([...bereitsGenannt, ...zusaetzlicheTicker]));

  return { ...n, betroffene_ticker_erweitert: erweitert, sektor_treffer: sektorTreffer };
}

// ─── News filtern ─────────────────────────────────────────────────────────────
const heutigeNews = alleNews
  .filter(n => {
    const d = String(n.datum_iso || n.datum || '');
    return d.startsWith(heute) && (n.relevanz === 'hoch' || n.relevanz === 'mittel');
  })
  .map(erweitereTickerFuerSektorNews);
diagnose.news_heute_relevant = heutigeNews.length;

// ─── Technische Signale ───────────────────────────────────────────────────────
let techSignale;
if (techAusDB.length > 0) {
  techSignale = techAusDB.filter(s => String(s.datum || '').startsWith(heute));
  if (techSignale.length === 0) techSignale = techAusDB;
} else {
  // Static Data Fallback
  techSignale = Object.values(sd.technischeSignale || {})
    .filter(s => s.zeitstempel && s.zeitstempel.startsWith(heute))
    .map(s => {
      const hb = s.handelsBewertung || {};
      return { ...s,
        handels_status:      hb.status     || s.handels_status      || '',
        handels_status_text: hb.statusText || s.handels_status_text || '',
        signal_staerke:      s.signalStaerke || s.signal_staerke    || '',
        aktueller_kurs:      s.aktuellerKurs  || s.aktueller_kurs
      };
    });
  diagnose.tech_fallback_static = true;
}
diagnose.tech_signale_verwendet = techSignale.length;

const statusPrio = { handelskandidat: 1, beobachten: 2, nur_info: 3, ignorieren: 4 };
techSignale.sort((a, b) =>
  (statusPrio[a.handels_status] || 9) - (statusPrio[b.handels_status] || 9)
);

// ─── Fundamentaldaten Fallback ───────────────────────────────────────────────
const fundamentalFinal = fundamentaldaten.length > 0
  ? fundamentaldaten
  : Object.values(sd.fundamentaldaten || {});
diagnose.fundamental_verwendet = fundamentalFinal.length;

// ─── Marktlage ────────────────────────────────────────────────────────────────
const HAUPT_SYMBOLE   = ['^GDAXI', '^STOXX50E', '^GSPC', '^IXIC'];
const KONTEXT_SYMBOLE = ['EURUSD=X', 'CL=F', 'GC=F'];
const hauptmaerkte    = marktKontext.filter(m => HAUPT_SYMBOLE.includes(m.symbol));
const kontextmaerkte  = marktKontext.filter(m => KONTEXT_SYMBOLE.includes(m.symbol));
const risk_off = hauptmaerkte.filter(m => m.markt_status === 'risk_off').length;
const risk_on  = hauptmaerkte.filter(m => m.markt_status === 'risk_on').length;
const gesamtMarktLage =
  marktKontext.length === 0 ? 'unbekannt' :
  risk_off > risk_on        ? 'risk_off'  :
  risk_on  > risk_off       ? 'risk_on'   : 'neutral';

const dax    = marktKontext.find(m => m.symbol === '^GDAXI')   || null;
const nasdaq = marktKontext.find(m => m.symbol === '^IXIC')    || null;
const sp500  = marktKontext.find(m => m.symbol === '^GSPC')    || null;
const eurusd = marktKontext.find(m => m.symbol === 'EURUSD=X') || null;
const oel    = marktKontext.find(m => m.symbol === 'CL=F')     || null;

// ─── Signale kategorisieren ───────────────────────────────────────────────────
const handelskandidaten = techSignale.filter(s => s.handels_status === 'handelskandidat');
const beobachtenListe   = techSignale.filter(s => s.handels_status === 'beobachten');
const marktBestaetigt   = techSignale.filter(s =>
  s.markt_bestaetigt_signal === 'true' &&
  (s.handels_status === 'handelskandidat' || s.handels_status === 'beobachten')
);
const marktGegenSignal  = techSignale.filter(s =>
  s.markt_bestaetigt_signal === 'false' &&
  (s.handels_status === 'handelskandidat' || s.handels_status === 'beobachten')
);
diagnose.handelskandidaten_count = handelskandidaten.length;
diagnose.beobachten_count        = beobachtenListe.length;
diagnose.markt_bestaetigt_count  = marktBestaetigt.length;

// ─── Empfehlungs-Watchlist (News+Signal-Positionen, hypothetisch) ────────────
const aktuellerKursByTicker = {};
for (const s of techAusDB) {
  if (s.ticker) aktuellerKursByTicker[String(s.ticker).trim()] = s.aktueller_kurs;
}

function berechneLivePerformance(row) {
  const entry = Number(row.entry_kurs);
  const aktuell = Number(aktuellerKursByTicker[String(row.ticker || '').trim()]);
  if (isNaN(entry) || isNaN(aktuell) || entry <= 0) return null;
  const pct = row.richtung === 'kauf'
    ? ((aktuell - entry) / entry) * 100
    : ((entry - aktuell) / entry) * 100;
  return parseFloat(pct.toFixed(2));
}

const offenePositionen = empfehlungenRows
  .filter(r => r.status === 'offen')
  .map(r => ({ ...r, live_performance_pct: berechneLivePerformance(r) }));

const geschlossenePositionen = empfehlungenRows.filter(r => r.status === 'geschlossen');

const geschlossenPerformances = geschlossenePositionen
  .map(r => Number(r.performance_pct))
  .filter(v => !isNaN(v));

const empfehlungswatchlist = {
  offen: offenePositionen,
  geschlossen: geschlossenePositionen,
  anzahl_offen: offenePositionen.length,
  anzahl_geschlossen: geschlossenePositionen.length,
  durchschnitt_performance_geschlossen: geschlossenPerformances.length > 0
    ? parseFloat((geschlossenPerformances.reduce((a, b) => a + b, 0) / geschlossenPerformances.length).toFixed(2))
    : null,
  trefferquote_geschlossen: geschlossenPerformances.length > 0
    ? parseFloat(((geschlossenPerformances.filter(v => v > 0).length / geschlossenPerformances.length) * 100).toFixed(1))
    : null
};

// ─── Report zusammenbauen ─────────────────────────────────────────────────────
return [{
  json: {
    datum:   new Date().toLocaleDateString('de-DE'),
    uhrzeit: new Date().toLocaleTimeString('de-DE'),

    technische_signale: techSignale,
    handelskandidaten,
    beobachten_liste:   beobachtenListe,
    markt_bestaetigt:   marktBestaetigt,
    markt_gegen_signal: marktGegenSignal,

    fundamentaldaten:   fundamentalFinal,
    nachrichten:        heutigeNews,
    empfehlungswatchlist,

    marktumfeld: {
      kontext:             marktKontext,
      gesamt_lage:         gesamtMarktLage,
      risk_on_count:       risk_on,
      risk_off_count:      risk_off,
      haupt_maerkte_count: hauptmaerkte.length,
      kontext_maerkte: kontextmaerkte.map(m => ({
        symbol: m.symbol, name: m.name,
        status: m.markt_status, veraenderung_pct: m.veraenderung_pct
      })),
      dax:    dax    ? { status: dax.markt_status,    trend: dax.trend,    veraenderung_pct: dax.veraenderung_pct,    risk_level: dax.risk_level,    hinweis: dax.markt_hinweis }    : null,
      nasdaq: nasdaq ? { status: nasdaq.markt_status, trend: nasdaq.trend, veraenderung_pct: nasdaq.veraenderung_pct, risk_level: nasdaq.risk_level, hinweis: nasdaq.markt_hinweis } : null,
      sp500:  sp500  ? { status: sp500.markt_status,  trend: sp500.trend,  veraenderung_pct: sp500.veraenderung_pct,  risk_level: sp500.risk_level,  hinweis: sp500.markt_hinweis }  : null,
      eurusd: eurusd ? { kurs: eurusd.aktueller_kurs, veraenderung_pct: eurusd.veraenderung_pct } : null,
      oel:    oel    ? { kurs: oel.aktueller_kurs,    veraenderung_pct: oel.veraenderung_pct }    : null
    },

    datenqualitaet: diagnose,

    debug: {
      fundamental_db:        fundamentaldaten.length,
      fundamental_ok:        diagnose.fundamental_ok,
      fundamental_fehler:    diagnose.fundamental_fehler,
      fundamental_verwendet: diagnose.fundamental_verwendet,
      tech_aus_db:           techAusDB.length,
      tech_heute:            diagnose.tech_signale_heute,
      tech_verwendet:        techSignale.length,
      markt_kontext:         marktKontext.length,
      news_total:            alleNews.length,
      news_heute_relevant:   heutigeNews.length,
      quellen_leer:          diagnose.quellen_leer,
      heute
    }
  }
}];

// DATENQUALITÄTS-CHECK VOR TAGESREPORT
// Modus: runOnceForAllItems
// Warnungen nur bei echten Problemen (fehlende Signale, Fundamental-Fehler, leerer Report).
// "Keine News heute" ist ein Hinweis, keine Warnung.

const alleItems = $input.all();
const reportdaten = alleItems[0]?.json || {};

const techSignale   = reportdaten.technische_signale || [];
const fundamentals  = reportdaten.fundamentaldaten   || [];
const nachrichten   = reportdaten.nachrichten        || [];
const kandidaten    = reportdaten.handelskandidaten  || [];
const beobachten    = reportdaten.beobachten_liste   || [];
const heute         = new Date().toISOString().substring(0, 10);

const fundFehler = fundamentals.filter(f =>
  f.status === 'fehler' || String(f.fehler || '').length > 0
).length;

const techFehler = techSignale.filter(s =>
  String(s.fehler || '').length > 0
).length;

const letzterTechZeitstempel = techSignale
  .map(s => s.zeitstempel || '')
  .filter(Boolean)
  .sort()
  .reverse()[0] || 'unbekannt';

const marktKontext = (reportdaten.marktumfeld && reportdaten.marktumfeld.kontext) || [];

const techHeuteCount = techSignale.filter(s => String(s.datum || '').startsWith(heute)).length;
const techStale = techSignale.length > 0 && techHeuteCount === 0;
const techStaleDatum = techStale
  ? (techSignale.map(s => s.datum || '').filter(Boolean).sort().reverse()[0] || 'unbekannt')
  : null;

const marktKontextHeuteCount = marktKontext.filter(m => String(m.datum || '').startsWith(heute)).length;
const marktKontextStale = marktKontext.length > 0 && marktKontextHeuteCount === 0;
const marktKontextStaleDatum = marktKontextStale
  ? (marktKontext.map(m => m.datum || '').filter(Boolean).sort().reverse()[0] || 'unbekannt')
  : null;

const fundamentalHeuteCount = fundamentals.filter(f => String(f.datum || '').startsWith(heute)).length;
const fundamentalStale = fundamentals.length > 0 && fundamentalHeuteCount === 0;
const fundamentalStaleDatum = fundamentalStale
  ? (fundamentals.map(f => f.datum || '').filter(Boolean).sort().reverse()[0] || 'unbekannt')
  : null;

const newsHochMittel = nachrichten.filter(n =>
  n.relevanz === 'hoch' || n.relevanz === 'mittel'
).length;

const reportKompLettLeer =
  techSignale.length === 0 &&
  fundamentals.length === 0 &&
  nachrichten.length === 0;

// Warnungen: nur echte Workflow-Probleme
const warnungen = [
  ...(techSignale.length < 10 && techSignale.length > 0
      ? [`Nur ${techSignale.length} technische Signale (erwartet: 15)`] : []),
  ...(techSignale.length === 0
      ? ['KEINE technischen Signale – Kurs-Strang prüfen'] : []),
  ...(techStale
      ? [`VERALTET: Technische Signale sind nicht von heute (zuletzt: ${techStaleDatum}) – Workflow 02 Technische Signale prüfen`] : []),
  ...(marktKontextStale
      ? [`VERALTET: Marktumfeld ist nicht von heute (zuletzt: ${marktKontextStaleDatum}) – Workflow 02b Marktumfeld prüfen`] : []),
  ...(fundamentalStale
      ? [`VERALTET: Fundamentaldaten sind nicht von heute (zuletzt: ${fundamentalStaleDatum}) – Workflow 01 Fundamentaldaten prüfen`] : []),
  ...(fundFehler > 5
      ? [`${fundFehler} Fundamentaldaten fehlerhaft`] : []),
  ...(reportKompLettLeer
      ? ['KRITISCH: Report hat keine Daten – gesamten Workflow prüfen'] : [])
];

// Hinweise: normale Betriebszustände, kein Alert
const hinweise = [
  ...(nachrichten.length === 0
      ? ['Keine relevanten News heute – normal außerhalb der Handelszeiten'] : []),
  ...(kandidaten.length === 0
      ? ['Heute keine Handelskandidaten – Markt seitwärts oder kein klares Signal'] : [])
];

const datenqualitaet = {
  fundamental_gesamt:          fundamentals.length,
  fundamental_fehler:          fundFehler,
  fundamental_ok:              fundamentals.length - fundFehler,
  fundamental_stale:           fundamentalStale,
  fundamental_stale_datum:     fundamentalStaleDatum,
  tech_signale_gesamt:         techSignale.length,
  tech_signale_fehler:         techFehler,
  tech_signale_ok:             techSignale.length - techFehler,
  tech_signale_stale:          techStale,
  tech_signale_stale_datum:    techStaleDatum,
  tech_kandidaten:             kandidaten.length,
  tech_beobachten:             beobachten.length,
  letzter_tech_zeitstempel:    letzterTechZeitstempel,
  markt_kontext_gesamt:        marktKontext.length,
  markt_kontext_stale:         marktKontextStale,
  markt_kontext_stale_datum:   marktKontextStaleDatum,
  news_gesamt:                 nachrichten.length,
  news_hoch_mittel:            newsHochMittel,
  heute,
  warnungen,
  hinweise
};

return [{ json: { ...reportdaten, datenqualitaet } }];

